  "localModels.requestTimeoutMs": { type: "number", description: "Budget of one request to the local model: the whole request for a unary completion, the idle gap between bytes for a stream (see `RuntimeLocalModelsConfig.requestTimeoutMs`). Default 300 000 ms. `ATOMIC_AGENT_LLAMA_REQUEST_TIMEOUT_MS`, when set, still wins over this file value (ATO-922)." },
  "localModels.useServerTemplate": { type: "'auto' | 'on' | 'off'", description: "Render local prompts through the model's own chat template (llama-server `POST /apply-template`) instead of atag's hand-built framing. `auto` (default) uses the template for every family without a hand-built profile — everything but Gemma and Qwen — so Llama, GLM, Mistral and other GGUFs get their turn markers." },
