  "localModels.reasoningBudgetTokens": { type: "number", description: "How many tokens a local reasoning model may spend thinking before a tool call, on the grammar path. The GBNF prelude bounds the think block at `reasoningBudgetTokens × 4` characters; past that the sampler admits only the close sentinel, so the model is forced to close the block and emit the call. `0` leaves the prelude unbounded." },
  "localModels.drySampler": { type: "boolean", description: "Turn on llama.cpp's DRY (\"don't repeat yourself\") sampler for every `/completion` request to a llama.cpp-family engine (Atomic Core, the managed llama-server, an External llama-server). It penalises a token that would extend a sequence already in the last 256 tokens of prompt plus reply, which targets the verbatim prose loops small models fall into." },
  "localModels.strictToolArgs": { type: "boolean", description: "Hold a local model's tool ARGUMENTS to each tool's JSON Schema on the grammar path, not only its tool names (ATO-633): a key the schema does not know, a missing required key or a value outside an `enum` cannot be sampled." },
  "localModels.managed.engine": { type: "'llama-server' | 'atomic-core'", description: "Managed process owner. Default `\"atomic-core\"`; files before v77 migrate to it (llama.cpp stays selectable)." },
