  "localModels.download.connections": { type: "number", description: "Parallel HTTP range requests one model or backend file is split across, 1 to 64. Default `16`; `1` downloads in a single stream. `ATOMIC_AGENT_DOWNLOAD_CONNECTIONS` wins when set." },
  "localModels.download.hfEndpoint": { type: "string", description: "Origin that serves Hugging Face for this install, e.g. a regional mirror. Catalogue and custom-model URLs stay canonical `https://huggingface.co/...`; the endpoint is applied at request time, so switching it never invalidates a partial download. The `HF_ENDPOINT` env var (what `huggingface_hub` honours) wins over this value when set." },
  "localModels.customModels": { type: "LocalModelDef[]", description: "GGUF models the operator added from an arbitrary Hugging Face repo. Each entry is a whole `LocalModelDef` with a `custom-` prefixed id; `loadConfig()` publishes them to the catalog registry so curated and added models resolve through one lookup. Older files inherit `[]`." },
  "log.level": { type: "'debug' | 'info' | 'warn' | 'error'", description: "Lowest severity the runtime's structured log writes: `debug`, `info` (default), `warn` or `error`." },
  "agent.tokenBudget": { type: "number", description: "Compact target for the upper prompt. Its only remaining effect on a built prompt is the `### session-facts` + `### loaded-skills` share, and `sessionSectionsMaxTokens` now overrides that directly; the stable prefix is sized by what it contains, not by this number." },
  "agent.maxSteps": { type: "number", description: "Steps in one leg of a task — a checkpoint, not the end of it." },
