  "agent.task.resumeInterrupted": { type: "boolean", description: "Continue a durable task whose run a crash, a kill or a restart cut off, from its session's per-step checkpoint, with a note telling the model how far it got (ATO-1109). Off: the run starts over from the task's message, as before. A run a person stopped is never resumed." },
  "agent.task.maxResumes": { type: "number", description: "Resumes after the agent died under a task (crash or kill) before the task is failed instead: the guard against a task that takes the agent down every time. `0` fails it at the first such interruption." },
  "agent.task.maxCostUsd": { type: "number", description: "Spend ceiling for one task, in USD, estimated from each completion's usage and the model's prices (prompt-cache aware). Reached, the task ends the same graceful way as the time ceiling. `0` means no cap. Unpriced models (a local model) count as $0, so this never stops local work. Default `0`." },
  "agent.task.replanEveryNSteps": { type: "number", description: "Ask the model to review and resend its live plan (`plan.update`) every this many steps of a long task (ATO-609). The request joins the next step's notice, so it costs no extra model call. `0` (the default) is off. Additive and unversioned: an older file has no field and never re-plans." },
  "agent.goal.maxTokens": { type: "number", description: "Token budget a new goal starts with: prompt plus completion tokens of all its rounds, as the provider reports them. `0` means no cap (rounds, time and money still bound a goal). `/goal tokens` changes it for one goal. Default `0`." },
  "agent.toolTimeoutMs": { type: "number", description: "Parsed as a positive number of milliseconds (default `60000`), but no tool reads it today, so it has no effect. The shell's wait is `tools.shell.defaultTimeoutMs`." },
  "agent.readScope": { type: "'working-dir' | 'unrestricted'", description: "Where a session's reads may go. `working-dir` (the default) confines filesystem reads and shell path arguments to the working directory and the paths the user named in the conversation; `unrestricted` is the pre-v67 behaviour." },
  "agent.approvalLevel": { type: "1 | 2 | 3 | 4 | 5", description: "Five-step approval ladder. Replaces the binary `approvalRequired`; the legacy key is still read once for migration (see `resolveApprovalLevel`) and never written back." },
  "agent.compaction.auto": { type: "boolean", description: "Compact the conversation automatically once its history reaches `triggerRatio` of the history allowance. `false` leaves only manual and overflow compaction. Default `true`." },
