  "agent.nameSessions": { type: "boolean", description: "Ask the model to name each session." },
  "agent.conversationLowWater": { type: "number", description: "Share of a limit the transcript keeps after a cut, `(0, 1]`. History is dropped in chunks — down to this share of the token budget or of `conversationMaxPairs`, whichever overflowed — and the cut then holds until the next overflow, so the prompt is append-only in between and a local model reuses its KV cache." },
  "agent.sessionSectionsMaxTokens": { type: "number", description: "Ceiling on `### session-facts` + `### loaded-skills` combined. One cap over two sections because one `truncateToTokens` call trims the two as a single blob, facts first, so the skill bodies at its tail are what a cut takes." },
  "agent.worldSnapshotMaxTokens": { type: "number", description: "Safety-net ceiling for the `### world` section. ARIA snapshots are already compressed at the browser layer; this cap guards against edge cases where compression misses (huge SVG trees, etc.)." },
  "agent.smartApproval": { type: "boolean", description: "Smart approval (ATO-465). When on, a request that would prompt, of a category the operator could grant for the session, is first rated by a model (`src/approval/risk-review.ts`): `low` runs it without a prompt, anything else and every failure prompts as before, with the rating shown. Off by default. Read live: no restart needed." },
  "agent.smartApprovalModel": { type: "string | null", description: "The `llm.providers[].id` the risk review runs on. `null` (default): a local `llama-server` link that has a model, else the active provider." },
