  "http.urlDataGuard": { type: "'off' | 'data' | 'strict'", description: "Ask before `os.web.fetch`, a GET `os.http.request` or the browser opens an address that carries data out (ATO-1377). `\"data\"` (default) asks only when the address carries a lot of data (a long value after `?`, an encoded blob, text with line breaks); `\"strict\"` also asks once per site per chat; `\"off\"` never asks." },
  "web.search.enabled": { type: "boolean", description: "Turns the `os.web.search` tool on. With `false` the tool is left out of the catalog and a call fails as disabled. Default `true`." },
  "web.search.provider": { type: "'duckduckgo' | 'searxng' | 'exa' | 'brave'", description: "Primary provider. The default `exa` uses its API endpoint when its `apiKeyEnv` resolves to a key, and its free keyless tier otherwise, with `duckduckgo` appended to the chain when it lacks it. The free tier runs out fast; a 429 parks it and the search result asks for a key (ATO-327). Existing configs need no rewrite for that." },
  "web.search.maxResults": { type: "number", description: "Results a search returns when the call does not ask for a number, 1 to 20. Default `8`." },
  "web.search.timeoutMs": { type: "number", description: "Timeout of one search provider request, in milliseconds. Default `15000`." },
  "web.search.cacheTtlMinutes": { type: "number", description: "Per-runtime result cache TTL in minutes. `0` disables caching. The cache is the primary defence against provider rate-limiting on repeated queries." },
  "web.search.persistCache": { type: "boolean", description: "Persist the result cache and the provider cooldown under `stateDir` (v46, #256), so a campaign that runs one process per task inherits both instead of starting cold and re-spending quota on queries the last process already answered. Key/TTL/eviction semantics are unchanged — only the storage moves." },
  "web.search.fallback": { type: "WebSearchProviderName[]", description: "Ordered fallback providers tried (after the primary) when a search is blocked / empty / throws. Default `[\"duckduckgo\"]` — DuckDuckGo's keyless HTML endpoint, which also takes over from a keyless Exa primary that hit its free limit." },
  "web.search.searxng.instanceUrl": { type: "string | null", description: "Base URL of the SearXNG instance the `searxng` provider queries. `null` (default) leaves SearXNG unconfigured, so the search chain skips it." },
